{
  "$schema": "https://open-design.ai/schemas/plugin.v1.json",
  "specVersion": "1.0.0",
  "name": "video-template-frame-creative-voltage",
  "title": "Creative Voltage Frame",
  "title_i18n": {
    "en": "Creative Voltage Frame",
    "zh-CN": "创意电压分屏帧"
  },
  "version": "0.1.0",
  "description": "Electric split with hand-drawn script — offset panels slide in, display title rises with an outlined word, script strokes itself in.",
  "description_i18n": {
    "en": "Electric split with hand-drawn script — offset panels slide in, display title rises with an outlined word, script strokes itself in.",
    "zh-CN": "创意电压分屏帧:电光蓝/暗错位分屏滑入 + 描边电光词 + 手写 script 自描, 复古现代有活力"
  },
  "license": "Apache-2.0",
  "author": {
    "name": "nexu-io",
    "url": "https://github.com/nexu-io",
    "contact": "open-design@nexu.io"
  },
  "homepage": "https://github.com/nexu-io/html-video/tree/main/templates/frame-creative-voltage",
  "tags": [
    "video-template",
    "first-party",
    "video",
    "hyperframes",
    "html-video",
    "motion",
    "split-panel",
    "electric",
    "script",
    "retro-modern",
    "voltage",
    "energetic",
    "presentation"
  ],
  "compat": {
    "agentSkills": [
      {
        "path": "./SKILL.md"
      }
    ]
  },
  "od": {
    "kind": "scenario",
    "taskKind": "new-generation",
    "mode": "video",
    "scenario": "video",
    "surface": "hyperframes",
    "engine": "hyperframes",
    "preview": {
      "type": "video",
      "poster": "https://cdn.jsdelivr.net/gh/nexu-io/open-design@main/plugins/_official/video-templates/frame-creative-voltage/preview.png",
      "video": "https://cdn.jsdelivr.net/gh/nexu-io/open-design@main/plugins/_official/video-templates/frame-creative-voltage/preview.mp4"
    },
    "useCase": {
      "query": {
        "en": "Use the Creative Voltage Frame template to turn my title into an energetic split reveal — electric-blue and dark panels sliding in offset, a display title rising with one outlined electric word, and a handwritten script stroking itself in. Preserve the template's visual signature, use real content, and avoid lorem ipsum or placeholder images.",
        "zh-CN": "用「创意电压分屏帧」模板把我的标题做成一段能量感分屏揭示:电光蓝与暗色面板错位滑入 + 标题升起带一个描边电光词 + 手写体自描入。保持模板的视觉签名,使用真实内容,避免 lorem ipsum 和占位图片。"
      }
    },
    "inputs": [
      {
        "name": "aspect",
        "label": "Aspect ratio",
        "type": "select",
        "options": [
          "16:9"
        ],
        "default": "16:9"
      },
      {
        "name": "format",
        "label": "Output format",
        "type": "select",
        "options": [
          "mp4",
          "webm"
        ],
        "default": "mp4"
      },
      {
        "name": "durationSec",
        "label": "Duration (seconds)",
        "type": "number",
        "default": 15
      }
    ],
    "context": {
      "skills": [
        {
          "path": "./SKILL.md"
        }
      ],
      "assets": [
        "./template.json",
        "./source"
      ]
    },
    "pipeline": {
      "stages": [
        {
          "id": "compose",
          "atoms": [
            "file-write"
          ]
        },
        {
          "id": "render",
          "atoms": [
            "media-video"
          ]
        }
      ]
    },
    "capabilities": [
      "prompt:inject",
      "fs:write",
      "media:video-generate"
    ],
    "provenance": {
      "origin": {
        "name": "none (original preset by the L2 skill author)",
        "kind": "none",
        "reference": "No specific real-world studio; the 'Creative Voltage' look is an original preset composed by the frontend-slides author"
      },
      "via_skill": {
        "name": "frontend-slides",
        "author": "Zara Zhang",
        "url": "https://github.com/zarazhangrui/frontend-slides",
        "license": "MIT",
        "source_file": "STYLE_PRESETS.md (preset \"Creative Voltage\")"
      },
      "transformation": "Static slide preset → animated hyperframes timeline (offset panels slide in, display title rises with one electric outlined word, handwritten script strokes itself in over a swept underline) built as original CSS/SVG keyframes. Original sample data. No upstream source code copied verbatim.\n"
    }
  }
}

